const stdout = $json.stdout ?? '';

const exitMatch = stdout.match(/__TEST_EXIT_CODE__=(\d+)/);

if (!exitMatch) {
  throw new Error('TEST_EXIT_CODE marker not found in SSH output');
}

const testExitCode = Number(exitMatch[1]);

const startMarker = '__TEST_RESULTS_JSON_START__';
const endMarker = '__TEST_RESULTS_JSON_END__';

const startIndex = stdout.indexOf(startMarker);
const endIndex = stdout.indexOf(endMarker);

if (startIndex === -1) {
  throw new Error('TEST_RESULTS_JSON_START marker not found');
}

if (endIndex === -1) {
  throw new Error('TEST_RESULTS_JSON_END marker not found');
}

const jsonText = stdout
  .substring(
    startIndex + startMarker.length,
    endIndex
  )
  .trim();

let testResults;

try {
  testResults = JSON.parse(jsonText);
} catch (error) {
  throw new Error(
    `Failed to parse Playwright JSON report: ${error.message}`
  );
}

const stats = testResults.stats ?? {};

return [
  {
    json: {
      testExitCode,

      summary: {
        expected: stats.expected ?? 0,
        unexpected: stats.unexpected ?? 0,
        skipped: stats.skipped ?? 0,
        flaky: stats.flaky ?? 0,
        durationMs: stats.duration ?? 0,
      },

      testResults,
    },
  },
];

const input = $input.first().json;

const testResults = input.testResults ?? {};
const failedTests = [];

/**
 * Recursively walk through Playwright suites.
 * Playwright can place specs directly under a suite
 * or inside nested suites.
 */
function processSuite(suite, parentSuiteTitle = '') {
  const suiteTitle = suite.title || parentSuiteTitle;

  // Process specs directly under this suite
  for (const spec of suite.specs ?? []) {
    const specFile = spec.file ?? '';
    const specTitle = spec.title ?? '';
    const specLine = spec.line ?? null;
    const specColumn = spec.column ?? null;

    for (const test of spec.tests ?? []) {
      for (const result of test.results ?? []) {
        if (result.status === 'failed') {
          const error = result.error ?? {};

          failedTests.push({
            title: specTitle,
            file: specFile,
            line: specLine,
            column: specColumn,
            suite: suiteTitle,
            status: result.status,
            durationMs: result.duration ?? 0,
            errorMessage: error.message ?? '',
            stack: error.stack ?? '',
            snippet: error.snippet ?? '',
            errors: result.errors ?? [],
            stdout: result.stdout ?? [],
            stderr: result.stderr ?? [],
          });
        }
      }
    }
  }

  // Recursively process nested suites
  for (const childSuite of suite.suites ?? []) {
    processSuite(childSuite, suiteTitle);
  }
}

// Process all top-level suites
for (const suite of testResults.suites ?? []) {
  processSuite(suite);
}

return [
  {
    json: {
      testExitCode: Number(input.testExitCode ?? 0),
      failedCount: failedTests.length,
      failedTests,
    },
  },
];

const failedTests = $json.failedTests ?? [];

function cleanAnsi(text) {
  return String(text)
    .replace(/\u001b\[[0-?]*[ -/]*[@-~]/g, '')
    .trim();
}

const failures = failedTests.map((test) => {
  const errors = (test.errors ?? []).map((error) => ({
    location: error.location ?? null,
    message: cleanAnsi(error.message ?? ''),
  }));

  return {
    testTitle: test.testTitle,
    file: test.file,
    line: test.line,
    durationMs: test.durationMs,
    errors,
  };
});

const analysisPrompt = `
You are an AI QA Automation Analyst.

Analyze the following Playwright test failures.

For each failed test, determine:

1. What failed?
2. The likely root cause.
3. Whether the failure appears to be:
   - application bug
   - test automation issue
   - environment/infrastructure issue
   - data issue
4. Recommended next debugging step.
5. A concise QA report.

Failed tests:

${JSON.stringify(failures, null, 2)}
`.trim();

return [
  {
    json: {
      testExitCode: $json.testExitCode,
      failedCount: failures.length,
      failures,
      analysisPrompt,
    },
  },
];

const summary = $json.summary ?? {};

return [
  {
    json: {
      status: 'PASS',
      testName: null,
      file: null,
      issueType: null,
      whatFailed: null,
      rootCause: null,
      recommendedNextStep: null,

      summary: {
        total: summary.expected ?? 0,
        failed: summary.unexpected ?? 0,
        skipped: summary.skipped ?? 0,
        flaky: summary.flaky ?? 0,
        durationMs: summary.durationMs ?? 0,
      },

      qaReport: `QA Test Run PASSED.

Total Tests: ${summary.expected ?? 0}
Failed: ${summary.unexpected ?? 0}
Skipped: ${summary.skipped ?? 0}
Flaky: ${summary.flaky ?? 0}
Duration: ${summary.durationMs ?? 0} ms

All executed Playwright tests passed successfully.`
    },
  },
];

const ai = $json.output ?? {};

return [
  {
    json: {
      status: 'FAIL',
      testName: ai.testName ?? '',
      file: ai.file ?? '',
      issueType: ai.issueType ?? '',
      whatFailed: ai.whatFailed ?? '',
      rootCause: ai.rootCause ?? '',
      recommendedNextStep: ai.recommendedNextStep ?? '',
      qaReport: ai.qaReport ?? '',
    },
  },
];

const items = $input.all();

if (items.length === 0) {
  throw new Error('No QA report received from PASS or FAIL branch');
}

const report = items[0].json;

const allowedStatuses = ['PASS', 'FAIL'];

if (!allowedStatuses.includes(report.status)) {
  throw new Error(
    `Invalid QA report status: ${report.status}`
  );
}

return [
  {
    json: {
      status: report.status,

      testName: report.testName ?? null,

      file: report.file ?? null,

      issueType: report.issueType ?? null,

      whatFailed: report.whatFailed ?? null,

      rootCause: report.rootCause ?? null,

      recommendedNextStep:
        report.recommendedNextStep ?? null,

      summary: report.summary ?? null,

      qaReport: report.qaReport ?? '',
    },
  },
];

const report = $json;

const timestamp = new Date().toISOString();

let markdown = `# AI QA Automation Report

## Test Run Summary

- **Status:** ${report.status}
- **Generated At:** ${timestamp}
`;

if (report.summary) {
  markdown += `
- **Total Tests:** ${report.summary.total}
- **Failed:** ${report.summary.failed}
- **Skipped:** ${report.summary.skipped}
- **Flaky:** ${report.summary.flaky}
- **Duration:** ${report.summary.durationMs} ms
`;
}

if (report.status === 'FAIL') {
  markdown += `

## Failure Analysis

### Test
${report.testName ?? 'N/A'}

### File
${report.file ?? 'N/A'}

### Issue Type
${report.issueType ?? 'N/A'}

### What Failed
${report.whatFailed ?? 'N/A'}

### Root Cause
${report.rootCause ?? 'N/A'}

### Recommended Next Step
${report.recommendedNextStep ?? 'N/A'}
`;
}

markdown += `

## QA Report

${report.qaReport ?? 'No QA report generated.'}
`;

const safeTimestamp = timestamp
  .replace(/[:.]/g, '-');

const fileName =
  `qa-report-${report.status.toLowerCase()}-${safeTimestamp}.md`;

return [
  {
    json: {
      ...report,
      reportFileName: fileName,
      reportMarkdown: markdown,
    },
  },
];
